/* @socom-skeleton body __ct__10CAppCameraFPQ23zdb6CWorldPQ23zdb7CCamera */
CAppCamera::CAppCamera(zdb::CWorld* world, zdb::CCamera* camera)
{
	m_cameraAim.x = 0.0f;
	m_cameraAim.y = 20.0f;
	m_cameraAim.z = 0.0f;

	m_cameraTie.x = 0.0f;
	m_cameraTie.y = 20.0f;
	m_cameraTie.z = 0.0f;

	m_camGoalPos.x = 40.0f;
	m_camGoalPos.y = 20.0f;
	m_camGoalPos.z = 0.0f;

	m_short_tether_timer = -1.0f;

	m_padid = 0;

	m_camera = camera;
	m_camera_effects = NULL;
	m_entity = NULL;

	m_z_nominal = 500.0f;
	m_camera_mode = PLAYER_CAM_STATE::cam_mode_tether;
	m_camera_last_mode = PLAYER_CAM_STATE::cam_mode_tether;

	m_cam_death_state = CAM_DEATH_STATE::none; /* 0x1eb818: sb zero,+0x94 (was m_death_state_timer) */

	f32 goalX = m_camGoalPos.x;
	f32 goalY = m_camGoalPos.y;
	f32 goalZ = m_camGoalPos.z;
	f32 goalSqr = (goalZ * goalZ) + (goalX * goalX) + (goalY * goalY);
	m_goal_t_len = goalSqr;

	CZSealBody* player = ftsGetPlayer();

	if (player)
	{
		bool isPlayer = false;

		if (player->m_control != NULL)
		{
			isPlayer = ((CSealCtrl*)player->m_control)->IsPlayer();
		}

		if (isPlayer)
		{
			m_padid = ((CSealCtrl*)player->m_control)->m_padid;
		}
	}

	m_entity = player;

	if (!m_entity)
	{
		m_camera_effects = NULL;
		m_skel_root = NULL;
	}
	else
	{
		zdb::CNode* playerNode = m_entity->GetNode();
		zdb::CNode* cameraEffects = playerNode->FindChild("camera_effects", true);
		m_camera_effects = cameraEffects;
		m_skel_root = m_entity->FindPart("skel_root");
	}

	m_wiggle_amp = theCharacterDynamics.m_cam_wiggle.amplitude;
	m_wiggle_duration = theCharacterDynamics.m_cam_wiggle.duration;
	m_wiggle_inv_duration = 1.0f / m_wiggle_duration;
	m_wiggle_rate = theCharacterDynamics.m_cam_wiggle.rate;
	m_wiggle_inv_rate = 1.0f / m_wiggle_rate;

	if (m_wiggle_echo)
	{
		m_wiggle_scalar = 1.0f;
	}
	else if (m_wiggle_scalar < 1.0f)
	{
		m_wiggle_scalar = 1.0f;
	}

	m_wiggle_cur_time = 0.0f;
	m_wiggle_echo = false;
}

/* @socom-skeleton body __dt__10CAppCameraFv */
CAppCamera::~CAppCamera()
{
	m_skel_root = NULL;
	m_entity = NULL;
	m_camera_effects = NULL;
	m_camera = NULL;
}

/* @socom-skeleton stub AttachTo__10CAppCameraFP10CZSealBody */
unsigned char CAppCamera::AttachTo(CZSealBody *seal)
{
	/* 0x1eb420 (virtual; testLoad calls it with the player): follow the seal from the
	   third-person view - its camera params (theCharacterDynamics), the player's pad, the
	   seal's "camera_effects" node and "skel_root" part - and place the camera behind it.
	   ELF quirk kept: m_z_nominal is stored twice, the second store (m_screenAspect.y) wins. */
	if (seal == NULL)
		return false;

	m_save_view = static_cast<CAMVIEW>(0);
	m_ctrl_view = static_cast<CAMVIEW>(0);
	m_save_peek = SEAL_PEEK::PEEK_NONE; /* 2 */

	CCameraParams* params = &theCharacterDynamics.m_cam_params[static_cast<u8>(m_ctrl_view)];
	m_camGoalPos = params->m_cam_offset;
	params = &theCharacterDynamics.m_cam_params[static_cast<u8>(m_ctrl_view)];
	m_cameraAim = params->m_cam_aimpoint;
	m_goal_t_len = sqrtf(m_camGoalPos.x * m_camGoalPos.x + m_camGoalPos.y * m_camGoalPos.y + m_camGoalPos.z * m_camGoalPos.z);
	m_cameraTie = m_cameraAim;

	CEntityCtrl* control = seal->m_control;

	if (control != NULL && static_cast<CSealCtrl*>(control)->IsPlayer())
		m_padid = static_cast<CSealCtrl*>(control)->m_padid;

	m_entity = seal;

	if (m_entity != NULL)
	{
		m_camera_effects = m_entity->GetNode()->FindChild("camera_effects", true);
		m_skel_root = m_entity->FindPart("skel_root");
	}
	else
	{
		m_camera_effects = NULL;
		m_skel_root = NULL;
	}

	CPnt3D eye = m_camGoalPos;
	m_entity->m_node->m_matrix.Transform(&eye, 1);

	CPnt3D aim = m_cameraAim;
	m_entity->m_node->m_matrix.Transform(&aim, 1);

	CMatrix matrix;
	sceVu0UnitMatrix(matrix.m_matrix);
	LookAt(&eye, &aim, matrix);
	m_camera->SetMatrix(&matrix);

	m_z_nominal = m_camera->m_screenAspect.x;
	m_z_nominal = m_camera->m_screenAspect.y;
	return true;
}

/* @socom-skeleton body SetZoom__10CAppCameraFf */
void CAppCamera::SetZoom(f32 zoom)
{
	/* 0x1eb3f0: the zoom scales the screen aspect (camera +0x440/+0x444, DWARF
	   m_screenAspect; was m_Zmin/m_Zmax) and the range scale is its inverse */
	m_camera->m_screenAspect.x = zoom;
	m_camera->m_screenAspect.y = zoom;
	m_camera->m_RangeScale = 1.0f / zoom;
}

/* @socom-skeleton body FTSTick__10CAppCameraFf */
/* @socom-skeleton body FTSTick__10CAppCameraFf */
void CAppCamera::FTSTick(f32 dT)
{
	/* 0x1eb0d0: the FTS view. The controlling pad (the player's, else pad 0) cycles the
	   view on SELECT+DOWN - skipping side, first person and the peeks, so with the shipped
	   camera params it stays on third person; a view change loads that view's offset and
	   aim point, places the camera behind the seal and picks tether or first person. */
	if (m_entity == NULL)
		return;

	CSealCtrl* control = static_cast<CSealCtrl*>(m_entity->m_control);
	bool isPlayer = control != NULL ? control->IsPlayer() : false;

	if (isPlayer)
		m_padid = control->m_padid;

	CPad* pad = m_padid < 2 ? CInput::m_pads[m_padid] : NULL;

	if (pad == NULL)
		pad = CInput::m_pads[0];

	if (pad != NULL && pad->GetTwoButtons(PAD_BUTTON::PAD_SELECT, PAD_BUTTON::PAD_DOWN))
	{
		u8 view = static_cast<u8>(m_ctrl_view);

		do
		{
			view = (view + 1) % theCharacterDynamics.m_cam_params.size();
		} while (view == 3 || view == 4 || static_cast<u8>(view - 1) < 2);

		m_ctrl_view = static_cast<CAMVIEW>(view);
	}

	if (m_ctrl_view == m_save_view)
		return;

	m_camGoalPos = theCharacterDynamics.m_cam_params[static_cast<u8>(m_ctrl_view)].m_cam_offset;
	m_cameraAim = theCharacterDynamics.m_cam_params[static_cast<u8>(m_ctrl_view)].m_cam_aimpoint;
	m_goal_t_len = sqrtf(m_camGoalPos.x * m_camGoalPos.x + m_camGoalPos.y * m_camGoalPos.y + m_camGoalPos.z * m_camGoalPos.z);
	m_cameraTie = m_cameraAim;

	if (m_entity != NULL)
	{
		CMatrix mat;
		sceVu0UnitMatrix(mat.m_matrix);
		CPnt3D eye = m_camGoalPos;
		m_entity->m_node->m_matrix.Transform(&eye, 1);
		CPnt3D aim = m_cameraAim;
		m_entity->m_node->m_matrix.Transform(&aim, 1);
		LookAt(&eye, &aim, mat);
		m_camera->SetMatrix(&mat);
	}

	m_save_view = m_ctrl_view;

	if (m_ctrl_view == CAMVIEW::cam_view_first)
		m_camera_mode = PLAYER_CAM_STATE::cam_mode_FP;
	else
		m_camera_mode = PLAYER_CAM_STATE::cam_mode_tether;
#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("CAM: view %d, camera mode %d", (int)m_ctrl_view, (int)m_camera_mode);
#endif
}

/* @socom-skeleton stub GetFirstPersonCamPos__FP10CAppCamera */
CPnt3D GetFirstPersonCamPos(CAppCamera *camera)
{
	/* 0x1eafc0 (returns the eye by value, MW hidden pointer in a0, the camera in a1): the
	   first-person eye in body space - the seal's skel_root (origin without one) raised
	   Y_FP_OFFSET, at z 3, shifted by the peek (3.3 left, 4.35 right per unit). */
	CPnt3D p;

	if (camera->m_entity != NULL && camera->m_skel_root != NULL)
		camera->m_entity->PartInSpace(camera->m_skel_root, NULL, &p, NULL);
	else
		p = CPnt3D::zero;

	f32 peek = 0.0f;

	if (peekCur < 0.0f)
		peek += 3.3f * peekCur;
	else if (!(peekCur <= 0.0f))
		peek += 4.35f * peekCur;

	p.z = 3.0f;
	p.y += Y_FP_OFFSET;
	p.x += peek;
	return p;
}

/* @socom-skeleton stub GetThirdPersonCamPos__10CAppCameraFP6CPnt3DPf */
/* @socom-skeleton stub GetThirdPersonCamPos__10CAppCameraFP6CPnt3DPf */
CPnt3D CAppCamera::GetThirdPersonCamPos(CPnt3D *aim, float *dist)
{
	/* 0x1ead60 (returns the eye by value, MW hidden pointer in a0): from the seal's
	   skel_root (body space; origin without one) raised 10 and shifted by the peek
	   (2.5 left, 2.8 right per unit), 28 behind: the aim gets that x/y and, in z, the
	   pitch term (CamRotZ_up/down times the look direction's y); the eye lies along the
	   seal's look quaternion from it, at the flat offset length eased toward 14 as the
	   look tilts. */
	CPnt3D p;

	if (m_entity != NULL && m_skel_root != NULL)
		m_entity->PartInSpace(m_skel_root, NULL, &p, NULL);
	else
		p = CPnt3D::zero;

	p.y += 10.0f;

	if (peekCur < 0.0f)
		p.x += 2.5f * peekCur;
	else
		p.x += 2.8f * peekCur;

	p.z += 28.0f;

	aim->x = p.x;
	aim->y = p.y;
	p.y = 0.0f;
	*dist = sqrtf(p.x * p.x + p.y * p.y + p.z * p.z);

	m_entity->m_fwdlook.Apply(&p, &p, 1);

	CPnt3D dir = p;
	dir.Normalize();

	if (dir.y < 0.0f)
		aim->z = dir.y * CamRotZ_up;
	else
		aim->z = dir.y * CamRotZ_down;

	f32 d = *dist;
	*dist = d + fabsf(dir.y) * (14.0f - d);

	CPnt3D scaled;
	dir.Scale(*dist, &scaled);
	p = scaled;
	p.Add(aim, &p);
	return p;
}

/* port: file-local helper, not an ELF function - the [0, 2pi] wrap both transitions repeat
   inline (0x1eac50 / 0x1ea9c8, each angle's two loops): up while below 0, down while above
   2pi. ELF quirk kept: a NaN never leaves the second loop. */
static inline f32 WrapTwoPi(f32 a)
{
	while (a < 0.0f)
		a += 6.2831855f; /* 0x40c90fdb */

	while (!(a <= 6.2831855f))
		a -= 6.2831855f;

	return a;
}

/* @socom-skeleton body ThirdToFirstPersonTransition__FP10CAppCamera */
void ThirdToFirstPersonTransition(CAppCamera* camera)
{
	/* 0x1eaae0 (CAppCamera::Tick, entering first person): keep the view on the player's aim
	   point. In body space, the pitch (atan2 of y over z) of the look line from the
	   first-person eye and the pitch of the aim point from it, both wrapped to [0, 2pi]:
	   the aim pitch moves by their difference and the head (the forward look) follows. */
#ifdef SOCOM_PORT
	/* port: m_aim_point is only set by CheckDIShoot -> SetAimPointW (not written), which the
	   ELF runs every camera tick, so the player always has one by now. Without one the aim
	   pitch is left as it is (the never-written member is heap garbage and a NaN would
	   never leave WrapTwoPi). */
	if (!ftsGetPlayer()->m_aim_point_valid)
	{
		SOCOM_PORT_TRACE("CAM: into first person without an aim point: aim pitch %.3f kept",
			static_cast<CSealCtrl*>(camera->m_entity->m_control)->m_aimPitch);
		return;
	}
#endif
	CPnt3D eye = GetFirstPersonCamPos(camera);
	CPnt3D ahead(0.0f, 0.0f, -1.0f);
	CPnt3D look;
	camera->m_entity->m_fwdlook.Apply(&ahead, &look, 1);
	look.Add(&eye, &look);
	f32 view = atan2f(look.y - eye.y, look.z - eye.z);

	CPnt3D aim = ftsGetPlayer()->m_aim_point;
	CMatrix inverse;
	sceVu0UnitMatrix(inverse.m_matrix);
	Vu0MatrixInverseWithUniformScale(&inverse, &camera->m_entity->m_node->m_matrix);
	inverse.Transform(&aim, 1);
	f32 target = atan2f(aim.y - eye.y, aim.z - eye.z);

	view = WrapTwoPi(view);
	target = WrapTwoPi(target);

	CSealCtrl* control = static_cast<CSealCtrl*>(camera->m_entity->m_control);
	control->m_aimPitch += view - target;
	ftsGetPlayer()->RotateHead(control->m_aimPitch, 0.0f);
}

/* @socom-skeleton body FirstToThirdPersonTransition__FP10CAppCamera */
void FirstToThirdPersonTransition(CAppCamera* camera)
{
	/* 0x1ea850 (CAppCamera::Tick, leaving first person): as ThirdToFirstPersonTransition,
	   from the third-person aim point (GetThirdPersonCamPos) and a look line 1000 long. */
#ifdef SOCOM_PORT
	/* port: see ThirdToFirstPersonTransition (no aim point without CheckDIShoot) */
	if (!ftsGetPlayer()->m_aim_point_valid)
		return;
#endif
	CPnt3D from;
	f32 dist;
	camera->GetThirdPersonCamPos(&from, &dist); /* the eye is unused */
	CPnt3D ahead(0.0f, 0.0f, -1000.0f);
	CPnt3D look;
	camera->m_entity->m_fwdlook.Apply(&ahead, &look, 1);
	look.Add(&from, &look);
	f32 view = atan2f(look.y - from.y, look.z - from.z);

	CPnt3D aim = ftsGetPlayer()->m_aim_point;
	CMatrix inverse;
	sceVu0UnitMatrix(inverse.m_matrix);
	Vu0MatrixInverseWithUniformScale(&inverse, &camera->m_entity->m_node->m_matrix);
	inverse.Transform(&aim, 1);
	f32 target = atan2f(aim.y - from.y, aim.z - from.z);

	view = WrapTwoPi(view);
	target = WrapTwoPi(target);

	CSealCtrl* control = static_cast<CSealCtrl*>(camera->m_entity->m_control);
	control->m_aimPitch += view - target;
	ftsGetPlayer()->RotateHead(control->m_aimPitch, 0.0f);
}

/* @socom-skeleton body TickCameraWiggle__10CAppCameraFfPQ23zdb7CCamera */
void CAppCamera::TickCameraWiggle(f32 dT, zdb::CCamera* camera)
{
	f32 wiggle = 0.0f;
	f32 wiggle_cur_time = m_wiggle_cur_time;

	if (m_wiggle_duration < wiggle_cur_time)
	{
		camera->m_screen.right = 0;
		camera->m_screen.bottom = 0;
		m_wiggle_echo = false;
	}
	else
	{
		f32 wiggle_inv_duration = wiggle_cur_time * m_wiggle_inv_duration;
		wiggle_cur_time *= 2.0f * PI * m_wiggle_inv_rate;

		if (wiggle_inv_duration < 0.0f)
		{
			wiggle_inv_duration = 0.0f;
		}

		wiggle = 1.0f;

		if (wiggle_inv_duration <= 1.0f)
		{
			wiggle = wiggle_inv_duration;
		}

		wiggle = (1.0f - wiggle) * m_wiggle_amp * m_wiggle_scalar;
		wiggle_inv_duration = sinf(wiggle_cur_time);
		camera->m_screen.right = wiggle * wiggle_cur_time + camera->m_screen.right;
		camera->m_screen.bottom = wiggle * 0.5 * wiggle_inv_duration + camera->m_screen.bottom;
		m_wiggle_cur_time += dT;
	}
}

/* @socom-skeleton body Tick__10CAppCameraFf */
/* @socom-skeleton body Tick__10CAppCameraFf */
void CAppCamera::Tick(f32 dT)
{
	/* 0x1ea480 (virtual, the camera owner's frame tick from CCoreState::Tick): unless the
	   camera is under animation control, run the FTS view logic, ease the peek toward
	   the seal's desired peek (exponential decay at m_cameraPeekDecayRate), build this
	   frame's camera matrix for the current mode (tether / first person / look-at),
	   apply the "camera_effects" node, set it on the camera, test the aim line for the
	   FTS game, and run the wiggle. ELF quirk kept: the decay time is RCNT0 in seconds
	   (RCNT0 * zSys.timerScale), not dT. */
	if (!zdb::CCamera::GetDynamicsControl())
		return;

	CMatrix mat;
	sceVu0UnitMatrix(mat.m_matrix);
	FTSTick(dT);

	f32 peekGoal;
	s8 state = m_entity->m_state;

	if (state == static_cast<s8>(SEAL_STATE::stateDead) || state == static_cast<s8>(SEAL_STATE::stateProne))
	{
		peekGoal = 0.0f;
	}
	else if (m_entity->m_desiredPeek == SEAL_PEEK::PEEK_LEFT)
	{
		peekGoal = -1.0f;
	}
	else if (m_entity->m_desiredPeek == SEAL_PEEK::PEEK_RIGHT)
	{
		peekGoal = 1.0f;
	}
	else
	{
		peekGoal = 0.0f;
	}

	f32 seconds = (f32)*T0_COUNT * zSys.timerScale;
	f32 decay = expf(-theCharacterDynamics.m_cameraPeekDecayRate * seconds);
	peekCur = peekGoal + (peekCur - peekGoal) * decay;

	switch (m_camera_mode)
	{
	case PLAYER_CAM_STATE::cam_mode_net:
		break;

	case PLAYER_CAM_STATE::cam_mode_apLook:
		APLookAt(dT, m_track, mat);
		break;

	case PLAYER_CAM_STATE::cam_mode_FP:
		if (m_camera_last_mode == PLAYER_CAM_STATE::cam_mode_tether)
			ThirdToFirstPersonTransition(this);

		APFirstPersonCam(mat);
		break;

	case PLAYER_CAM_STATE::cam_mode_tether:
		if (m_camera_last_mode == PLAYER_CAM_STATE::cam_mode_FP)
			FirstToThirdPersonTransition(this);

		APTeatherCam(mat, dT);
		break;

	default:
		APTeatherCam(mat, dT);
		break;
	}

	m_camera_last_mode = m_camera_mode;

	if (m_camera_effects != NULL)
	{
		CMatrix effects;
		sceVu0UnitMatrix(effects.m_matrix);
		sceVu0MulMatrix(effects.m_matrix, mat.m_matrix, m_camera_effects->m_matrix.m_matrix);
		sceVu0CopyMatrix(mat.m_matrix, effects.m_matrix);
	}

	m_camera->SetMatrix(&mat);

	if (OurGameName.m_game_name == nameFTS)
		m_entity->CheckDIShoot(&m_wPos, &mat);

	if (m_wiggle_echo)
		TickCameraWiggle(dT, m_camera);
}

/* @socom-skeleton body WiggleScalar__10CAppCameraFf */
void CAppCamera::WiggleScalar(f32 wiggle)
{
	if (!m_wiggle_echo)
	{
		m_wiggle_scalar = wiggle;
	}
	else if (m_wiggle_scalar < wiggle)
	{
		m_wiggle_scalar = wiggle;
	}
}

/* @socom-skeleton body WiggleEcho__10CAppCameraFb */
void CAppCamera::WiggleEcho(bool echo)
{
	m_wiggle_echo = echo;

	if (echo)
	{
		m_wiggle_cur_time = 0.0f;
	}
}

